'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/customers — your end customers, auto-created from collect payloads.
 */
class Customers {
  constructor(client) {
    this.client = client;
  }

  /**
   * List customers.
   * @param {object} [params] Query params (e.g. page, limit, search)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/customers', params));
  }

  /**
   * Retrieve a customer by ID.
   * @param {string} id
   */
  retrieve(id) {
    return this.client.request('GET', `/v1/customers/${encodeURIComponent(id)}`);
  }

  /**
   * Update a customer.
   * @param {string} id
   * @param {object} params
   */
  update(id, params) {
    return this.client.request('PUT', `/v1/customers/${encodeURIComponent(id)}`, params);
  }

  /**
   * List a customer's transactions.
   * @param {string} id
   * @param {object} [params] Query params (e.g. page, limit)
   */
  transactions(id, params) {
    return this.client.request('GET', withQuery(`/v1/customers/${encodeURIComponent(id)}/transactions`, params));
  }
}

module.exports = Customers;
